import { toRaw } from 'vue';
import { request } from '@/request/request.js';

export const getSchool = (id) => {
    return request({
        url: '/address/school/' + id,
        method: 'get'
    })
}

export const listSchool = (params) => {
    return request({
        url: '/address/school/list',
        method: 'get',
        params: toRaw(params)
    })
}

export const listOpenedCity = () => {
    return request({
        url: '/address/city/opened',
        method: 'get'
    })
}

export const getOpenedCityByAdcode = (adcode) => {
    return request({
        url: '/address/city/adcode/' + adcode,
        method: 'get'
    })
}

export const getLegacySchoolId = (school) => {
    if (!school) return null
    return school.legacySchoolId || school.schoolId || school.id || null
}

export const buildAreaParams = (params = {}, school) => {
    const currentSchool = school || uni.getStorageSync('currentSchool') || {}
    const schoolId = params.schoolId || getLegacySchoolId(currentSchool)
    return {
        ...params,
        schoolId
    }
}
